const parse=c=>{const m=c.match(/[\d.]+/g); return m?m.map(Number):[0,0,0,0];};
const lum=([r,g,b])=>{const f=v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4)}; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b);};
const up=e=>e.parentElement || (e.getRootNode().host||null);
const bgOf=e=>{let x=e; while(x){const c=parse(getComputedStyle(x).backgroundColor); if(c.length<4||c[3]>0.9) if(!(c.length===4&&c[3]===0)) return c; x=up(x);} return [255,255,255];};
const all=[]; const walk=(root)=>{ root.querySelectorAll('*').forEach(e=>{ all.push(e); if(e.shadowRoot) walk(e.shadowRoot);}); }; walk(document);
const res=[]; const seen=new Set();
for(const e of all){ const own=[...e.childNodes].filter(n=>n.nodeType===3&&n.textContent.trim()).map(n=>n.textContent.trim()).join(' '); if(!own) continue; const cs=getComputedStyle(e); if(cs.visibility==='hidden'||cs.display==='none') continue; const r=e.getBoundingClientRect(); if(!r.width) continue; let fg=parse(cs.color); const bg=bgOf(e); if(fg.length===4&&fg[3]<1){fg=fg.slice(0,3).map((v,i)=>v*fg[3]+bg[i]*(1-fg[3]));} const L1=lum(fg),L2=lum(bg); const cr=(Math.max(L1,L2)+0.05)/(Math.min(L1,L2)+0.05); const fs=parseFloat(cs.fontSize), fw=+cs.fontWeight; const large= fs>=24||(fs>=18.66&&fw>=700); const key=own.slice(0,20)+cs.color+bg; if(cr<(large?3:4.5)){ if(seen.has(key)) continue; seen.add(key); res.push({txt:own.slice(0,40), tag:e.tagName, cls:(typeof e.className==='string'?e.className:'').slice(0,50), fg:cs.color, bg:bg.join(','), cr:cr.toFixed(2), fs, fw, op:cs.opacity});}}
return res;
}"}

